"""Bake OBJ sources into VX's compact .vxm model format.

Sources:
  * assets/models/*.obj          - heroes generated by tools/characters.py
  * .tmp-assets/<pack>/...obj    - Kenney CC0 dungeon/arena kit (see CREDITS.md)
  * generated props              - brazier, mote, rune circle

.vxm layout (little endian):
  magic   "VXM1"
  u32     version = 1
  u32     flags (bit 0: model is additive)
  u16     name length + name bytes
  f32[3]  bounds min, f32[3] bounds max
  u16     joint count
    u8 name length + name, i32 parent, f32[3] rest offset (parent space)
  u16     part count
    u16 joint, u32 vertex count, u32 tri count
    f32[3] vertices
    u32[3] indices
    u8[4]  triangle color (r, g, b, emissive)
"""
from __future__ import annotations

import json
import math
import os
import struct
from collections import Counter, OrderedDict

from PIL import Image

