# ---------------------------------------------------------------------------
# OBJ / MTL parsing
# ---------------------------------------------------------------------------

def parse_mtl(path):
    mats = {}
    cur = None
    if not os.path.exists(path):
        return mats
    for raw in open(path, encoding="utf-8", errors="ignore"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        tok = line.split()
        if tok[0] == "newmtl":
            cur = {"name": " ".join(tok[1:]), "kd": (1.0, 1.0, 1.0), "map": None}
            mats[cur["name"]] = cur
        elif cur is None:
            continue
        elif tok[0] == "Kd" and len(tok) >= 4:
            cur["kd"] = (float(tok[1]), float(tok[2]), float(tok[3]))
        elif tok[0] == "Ke" and len(tok) >= 4:
            cur["ke"] = (float(tok[1]), float(tok[2]), float(tok[3]))
        elif tok[0] in ("map_Kd", "map_kd") and len(tok) >= 2:
            cur["map"] = " ".join(tok[1:])
    return mats


class Obj:
    def __init__(self):
        self.verts = []
        self.uvs = []
        self.groups = OrderedDict()   # group -> [(mat, [(vi, ti), ...])]
        self.materials = {}

    def faces(self):
        for group, faces in self.groups.items():
            for mat, corners in faces:
                yield group, mat, corners


def parse_obj(path):
    obj = Obj()
    mtllib = None
    group = "root"
    mat = None
    for raw in open(path, encoding="utf-8", errors="ignore"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        tok = line.split()
        tag = tok[0]
        if tag == "v":
            obj.verts.append((float(tok[1]), float(tok[2]), float(tok[3])))
        elif tag == "vt":
            obj.uvs.append((float(tok[1]), float(tok[2]) if len(tok) > 2 else 0.0))
        elif tag in ("o", "g"):
            name = " ".join(tok[1:]) or "root"
            group = name
            obj.groups.setdefault(group, [])
        elif tag == "usemtl":
            mat = " ".join(tok[1:]) if len(tok) > 1 else None
        elif tag == "mtllib":
            mtllib = " ".join(tok[1:])
        elif tag == "f":
            corners = []
            for c in tok[1:]:
                bits = c.split("/")
                vi = int(bits[0])
                ti = int(bits[1]) if len(bits) > 1 and bits[1] else None
                if vi < 0:
                    vi = len(obj.verts) + vi
                else:
                    vi -= 1
                if ti is not None and ti < 0:
                    ti = len(obj.uvs) + ti
                elif ti is not None:
                    ti -= 1
                corners.append((vi, ti))
            if len(corners) < 3:
                continue
            for i in range(1, len(corners) - 1):
                obj.groups.setdefault(group, []).append(
                    (mat, [corners[0], corners[i], corners[i + 1]]))
    if mtllib:
        obj.materials = parse_mtl(os.path.join(os.path.dirname(path), mtllib))
    return obj


# ---------------------------------------------------------------------------
# texture sampling (Kenney colormap)
# ---------------------------------------------------------------------------

class TextureSampler:
    def __init__(self, path):
        self.img = Image.open(path).convert("RGB")
        self.w, self.h = self.img.size
        self.cache = {}

    def at(self, u, v):
        key = (int(u * 4096), int(v * 4096))
        if key in self.cache:
            return self.cache[key]
        x = min(self.w - 1, max(0, int(u * self.w)))
        y = min(self.h - 1, max(0, int((1.0 - v) * self.h)))
        counts = Counter()
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                xx = min(self.w - 1, max(0, x + dx))
                yy = min(self.h - 1, max(0, y + dy))
                c = self.img.getpixel((xx, yy))
                if c == (0, 0, 0):
                    continue
                counts[c] += 1
        color = counts.most_common(1)[0][0] if counts else (0, 0, 0)
        self.cache[key] = color
        return color


def sample_face(texture, uv_list):
    colors = Counter()
    for u, v in uv_list:
        colors[texture.at(u, v)] += 3
    if len(uv_list) >= 3:
        cu = sum(u for u, _ in uv_list) / len(uv_list)
        cv = sum(v for _, v in uv_list) / len(uv_list)
        colors[texture.at(cu, cv)] += 4
    return colors.most_common(1)[0][0]


# ---------------------------------------------------------------------------
# baking helpers
# ---------------------------------------------------------------------------

def dedupe_faces(faces):
    seen = set()
    out = []
    for group, mat, corners in faces:
        key = (group, tuple(c[0] for c in corners))
        if key in seen:
            continue
        seen.add(key)
        out.append((group, mat, corners))
    return out


def normalize_geometry(verts):
    xs = [p[0] for p in verts]
    ys = [p[1] for p in verts]
    zs = [p[2] for p in verts]
    if not xs:
        return verts
    off = ((min(xs) + max(xs)) * 0.5, min(ys), (min(zs) + max(zs)) * 0.5)
    return [tuple(p[i] - off[i] for i in range(3)) for p in verts]


def pack_model(name, joints, parts, bounds_min, bounds_max, additive=False):
    out = bytearray()
    out += b"VXM1"
    out += struct.pack("<II", 1, 1 if additive else 0)
    nb = name.encode("utf-8")
    out += struct.pack("<B", len(nb)) + nb
    out += struct.pack("<6f", *bounds_min, *bounds_max)
    out += struct.pack("<H", len(joints))
    for jname, parent, rest in joints:
        jb = jname.encode("utf-8")
        out += struct.pack("<B", len(jb)) + jb
        out += struct.pack("<i3f", parent, *rest)
    out += struct.pack("<H", len(parts))
    for joint_index, verts, tris, colors in parts:
        out += struct.pack("<HII", joint_index, len(verts), len(tris))
        for p in verts:
            out += struct.pack("<3f", *p)
        for a, b_, c in tris:
            out += struct.pack("<III", a, b_, c)
        for (r, g, bb, em) in colors:
            out += struct.pack("<4B", r, g, bb, em)
    return bytes(out)


def build_parts_from_obj(name, obj, joint_names, joint_pivots, texture, default_joint="root"):
    joint_index = {jn: i for i, jn in enumerate(joint_names)}
    parts_raw = OrderedDict()
    bounds_min = [1e9, 1e9, 1e9]
    bounds_max = [-1e9, -1e9, -1e9]

    for group, matname, corners in obj.faces():
        ji = joint_index.get(group, joint_index.get(default_joint, 0))
        material = obj.materials.get(matname or "", {})
        kd = material.get("kd", (1.0, 1.0, 1.0))
        emissive = 1 if material.get("ke") else 0
        if material.get("map") and texture is not None:
            uvs = []
            for _, ti in corners:
                if ti is not None and 0 <= ti < len(obj.uvs):
                    uvs.append(obj.uvs[ti])
            color = sample_face(texture, uvs) if len(uvs) >= 3 else (255, 255, 255)
        else:
            color = (int(round(kd[0] * 255)), int(round(kd[1] * 255)), int(round(kd[2] * 255)))
        key = (ji, color, emissive)
        parts_raw.setdefault(key, []).append([obj.verts[vi] for vi, _ in corners])
        for vi, _ in corners:
            p = obj.verts[vi]
            for k in range(3):
                bounds_min[k] = min(bounds_min[k], p[k])
                bounds_max[k] = max(bounds_max[k], p[k])

    per_joint = OrderedDict()
    for (ji, color, emissive), tris in parts_raw.items():
        pivot = joint_pivots[joint_names[ji]]
        entry = per_joint.setdefault(ji, {"verts": [], "index": {}, "tris": [], "colors": []})
        for tri in tris:
            ids = []
            for p in tri:
                local = (p[0] - pivot[0], p[1] - pivot[1], p[2] - pivot[2])
                key = tuple(round(c, 6) for c in local)
                idx = entry["index"].get(key)
                if idx is None:
                    idx = len(entry["verts"])
                    entry["index"][key] = idx
                    entry["verts"].append(local)
                ids.append(idx)
            entry["tris"].append(tuple(ids))
            entry["colors"].append((color[0], color[1], color[2], 255 if emissive else 0))

    parts = []
    for ji, entry in per_joint.items():
        parts.append((ji, entry["verts"], entry["tris"], entry["colors"]))
    return parts, (bounds_min, bounds_max)


def load_rig(name):
    path = os.path.join(SRC_MODELS, name + ".rig.json")
    if not os.path.exists(path):
        return None
    return json.load(open(path, encoding="utf-8"))


def bake_character(name):
    obj_path = os.path.join(SRC_MODELS, name + ".obj")
    rig = load_rig(name)
    obj = parse_obj(obj_path)
    joint_names = [j["name"] for j in rig["joints"]]
    joint_pivots = {j["name"]: tuple(j["world"]) for j in rig["joints"]}
    parent_index = []
    for j in rig["joints"]:
        parent_index.append(joint_names.index(j["parent"]) if j["parent"] else -1)
    joints = [(j["name"], parent_index[i], tuple(j["rest"])) for i, j in enumerate(rig["joints"])]
    parts, bounds = build_parts_from_obj(name, obj, joint_names, joint_pivots, None)
    data = pack_model(name, joints, parts, bounds[0], bounds[1])
    write_baked(name, data)
    return name, sum(len(p[1]) for p in parts), sum(len(p[2]) for p in parts), data


def bake_kenney(name, pack, rel):
    obj_path = os.path.join(KENNEY, pack, "Models", "OBJ format", rel)
    if not os.path.exists(obj_path):
        print("  missing", obj_path)
        return None
    obj = parse_obj(obj_path)
    tex_path = os.path.join(os.path.dirname(obj_path), "Textures", "colormap.png")
    tex = TextureSampler(tex_path) if os.path.exists(tex_path) else None
    merged = []
    for group, faces in obj.groups.items():
        for mat, corners in faces:
            merged.append((mat, corners))
    merged = dedupe_faces([("root", m, c) for m, c in merged])
    obj.groups = OrderedDict([("root", [(m, c) for _, m, c in merged])])
    obj.verts = normalize_geometry(obj.verts)
    parts, bounds = build_parts_from_obj(name, obj, ["root"], {"root": (0.0, 0.0, 0.0)}, tex)
    data = pack_model(name, [("root", -1, (0.0, 0.0, 0.0))], parts, bounds[0], bounds[1])
    write_baked(name, data)
    return name, sum(len(p[1]) for p in parts), sum(len(p[2]) for p in parts), data


def write_baked(name, data):
    os.makedirs(OUT_BAKED, exist_ok=True)
    path = os.path.join(OUT_BAKED, name + ".vxm")
    with open(path, "wb") as f:
        f.write(data)


# ---------------------------------------------------------------------------
# extra generated props
# ---------------------------------------------------------------------------

def build_brazier():
    b = Builder(EXTRA_MATS)
    for i in range(3):
        a = 2.0 * math.pi * i / 3.0 + 0.5
        x = 0.13 * math.sin(a)
        z = 0.13 * math.cos(a)
        b.cylinder_between("root", "iron", (x, 0.0, z), (x * 0.55, 0.31, z * 0.55),
                           0.022, 0.016, 5)
        b.box("root", "iron", (x, 0.012, z), (0.045, 0.024, 0.045))
    b.frustum("root", "iron", (0.0, 0.345, 0.0), 0.105, 0.175, 0.120, 10,
              cap_bottom=True, cap_top=False)
    b.annulus("root", "gold", (0.0, 0.402, 0.0), 0.168, 0.190, 0.025, 10)
    b.frustum("root", "ember", (0.0, 0.390, 0.0), 0.120, 0.150, 0.030, 10,
              cap_bottom=True, cap_top=False)
    for i in range(7):
        a = 2.0 * math.pi * i / 7.0
        r = 0.035 + 0.065 * ((i * 37) % 11) / 11.0
        b.octahedron("root", "fire" if i % 2 == 0 else "ember",
                     (r * math.sin(a), 0.412, r * math.cos(a)), 0.034, (1.0, 0.45, 1.0))
    return b


def build_pylon():
    b = Builder(EXTRA_MATS)
    b.box("root", "stone_dark", (0.0, 0.11, 0.0), (0.72, 0.22, 0.72))
    b.box("root", "stone", (0.0, 0.26, 0.0), (0.56, 0.10, 0.56))
    b.taper_box("root", "stone_dark", (0.0, 0.95, 0.0), 1.32, (0.27, 0.27), (0.11, 0.11))
    b.taper_box("root", "stone", (0.0, 0.40, 0.0), 0.16, (0.27, 0.27), (0.24, 0.24))
    b.annulus("root", "gold", (0.0, 1.52, 0.0), 0.10, 0.145, 0.045, 8)
    b.annulus("root", "gold", (0.0, 0.62, 0.0), 0.205, 0.235, 0.035, 8)
    for i in range(4):
        a = 2.0 * math.pi * i / 4.0
        x = 0.19 * math.sin(a)
        z = 0.19 * math.cos(a)
        b.box("root", "glow_cyan", (x, 1.02, z), (0.045, 0.20, 0.045), rot=(0.0, -a, 0.0))
    b.octahedron("root", "glow_cyan", (0.0, 1.72, 0.0), 0.17, (1.0, 1.8, 1.0))
    b.octahedron("root", "cyan", (0.0, 1.72, 0.0), 0.11, (1.0, 1.8, 1.0))
    b.box("root", "stone_light", (0.0, 1.60, 0.0), (0.18, 0.04, 0.18))
    return b


def build_mote():
    b = Builder(EXTRA_MATS)
    b.octahedron("root", "white", (0.0, 0.04, 0.0), 0.035, (1.0, 1.35, 1.0))
    b.octahedron("root", "white", (0.0, 0.04, 0.0), 0.060, (1.0, 0.30, 1.0))
    return b


def build_rune_circle():
    b = Builder(EXTRA_MATS)
    b.annulus("root", "glow_cyan", (0.0, 0.012, 0.0), 1.02, 1.10, 0.012, 40)
    b.annulus("root", "glow_cyan", (0.0, 0.012, 0.0), 0.72, 0.76, 0.010, 32)
    for i in range(8):
        a = 2.0 * math.pi * i / 8.0
        x = 0.89 * math.sin(a)
        z = 0.89 * math.cos(a)
        b.box("root", "glow_cyan", (x, 0.014, z), (0.055, 0.010, 0.16), rot=(0.0, -a, 0.0))
        x2 = 0.66 * math.sin(a)
        z2 = 0.66 * math.cos(a)
        b.octahedron("root", "glow_cyan", (x2, 0.014, z2), 0.035, (1.0, 0.18, 1.0))
    for i in range(4):
        a = 2.0 * math.pi * i / 4.0 + math.pi / 8.0
        b.box("root", "glow_cyan", (0.50 * math.sin(a), 0.011, 0.50 * math.cos(a)),
              (0.018, 0.008, 0.60), rot=(0.0, -a, 0.0))
    return b


def bake_extra(name, builder, additive=False):
    joint_name = "root"
    verts = []
    index = {}
    tris = []
    colors = []
    for color, p0, p1, p2 in builder.tris.get(joint_name, []):
        rgb, em = EXTRA_MATS[color]
        ids = []
        for p in (p0, p1, p2):
            key = tuple(round(c, 6) for c in p)
            idx = index.get(key)
            if idx is None:
                idx = len(verts)
                index[key] = idx
                verts.append(p)
            ids.append(idx)
        tris.append(tuple(ids))
        colors.append((rgb[0], rgb[1], rgb[2], 255 if em else 0))
    parts = [(0, verts, tris, colors)]
    data = pack_model(name, [(joint_name, -1, (0.0, 0.0, 0.0))], parts,
                      builder.bounds_min, builder.bounds_max, additive)
    write_baked(name, data)
    return name, len(verts), len(tris), data


# ---------------------------------------------------------------------------
# zig asset manifest
# ---------------------------------------------------------------------------

def write_manifest(names):
    os.makedirs(os.path.dirname(OUT_ZIG), exist_ok=True)
    lines = ["// Generated by tools/bake_assets.py. Do not edit by hand.",
             "//",
             "// Every model is embedded into the executable so the game runs from any",
             "// working directory.",
             ""]
    for name in sorted(names):
        lines.append('pub const {0} = @embedFile("baked/{0}.vxm");'.format(name))
    lines.append("")
    lines.append("pub const Entry = struct { name: []const u8, bytes: []const u8 };")
    lines.append("")
    lines.append("pub const all = [_]Entry{")
    for name in sorted(names):
        lines.append('    .{{ .name = "{0}", .bytes = {0} }},'.format(name))
    lines.append("};")
    lines.append("")
    with open(OUT_ZIG, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines))


# ---------------------------------------------------------------------------
# credits
# ---------------------------------------------------------------------------

def write_credits(kenney_used):
    path = os.path.join(ROOT, "assets", "CREDITS.md")
    lines = ["# Asset credits", "",
             "## Heroes and generated props", "",
             "assets/models/*.obj and the brazier / mote / rune circle props are",
             "procedurally authored for VX by tools/characters.py and",
             "tools/bake_assets.py. They belong to this project.", "",
             "Skeleton, wraith, golem and abyss guard meshes share the same",
             "procedural humanoid rig as the heroes.", "",
             "## Kenney 3D kit", "",
             "The dungeon/arena props are derived from free Kenney 3D packs",
             "(CC0 1.0 Universal, public domain):", "",
             "- https://kenney.nl/assets/mini-dungeon",
             "- https://kenney.nl/assets/mini-arena", "",
             "Models used: " + ", ".join(sorted(kenney_used)) + ".", "",
             "Kenney's license text:",
             "", "~~~"]
    lic = os.path.join(KENNEY, "mini-dungeon", "License.txt")
    if os.path.exists(lic):
        lines.extend(open(lic, encoding="utf-8", errors="ignore").read().splitlines())
    lines.extend(["~~~", ""])
    lines.extend([
        "## UI font", "",
        "The Chinese HUD uses a subset of **Ark Pixel Font 12px** by TakWolf",
        "(https://github.com/TakWolf/ark-pixel-font), licensed under the",
        "SIL Open Font License 1.1. The license text is in assets/fonts/OFL.txt.",
        "Only glyph bitmaps for characters used by the game are embedded;",
        "the source BDF is not required at runtime.", "",
    ])
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines))


# ---------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------

def main():
    os.makedirs(OUT_BAKED, exist_ok=True)
    names = []
    print("heroes:")
    for name in ("warrior", "archmage", "chronomancer", "skeleton", "wraith", "golem", "abyss_guard"):
        n, nv, nt, data = bake_character(name)
        names.append(n)
        print("  {:<14} verts={:5d} tris={:5d} bytes={:7d}".format(n, nv, nt, len(data)))

    print("kenney props:")
    used = []
    for name, pack, rel in KENNEY_PROPS:
        res = bake_kenney(name, pack, rel)
        if res is None:
            continue
        n, nv, nt, data = res
        names.append(n)
        used.append(name)
        print("  {:<14} verts={:5d} tris={:5d} bytes={:7d}".format(n, nv, nt, len(data)))

    print("generated props:")
    for name, fn, additive in (("brazier", build_brazier, False),
                               ("pylon", build_pylon, False),
                               ("mote", build_mote, False),
                               ("rune_circle", build_rune_circle, True)):
        n, nv, nt, data = bake_extra(name, fn(), additive)
        names.append(n)
        print("  {:<14} verts={:5d} tris={:5d} bytes={:7d}".format(n, nv, nt, len(data)))

    write_manifest(names)
    write_credits(used)
    print("wrote", len(names), "models to", OUT_BAKED)
    print("total bytes:", sum(os.path.getsize(os.path.join(OUT_BAKED, n + ".vxm")) for n in names))


if __name__ == "__main__":
    main()